  ('22222222-2222-4222-8222-000000000008', 'architect', 'kiến trúc sư; người tạo dựng', 'The architect designed a modern house that uses very little energy.', 'Kiến trúc sư đã thiết kế một ngôi nhà hiện đại sử dụng rất ít năng lượng.', 'ˈɑrkəˌtɛkt', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'architecture', 'kiến trúc', 'The city is famous for its beautiful old architecture and narrow streets.', 'Thành phố nổi tiếng với kiến trúc cổ đẹp và những con phố hẹp.', 'ˈɑrkəˌtɛktʃər', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'argument', 'lập luận; cuộc tranh cãi', 'Her main argument is that schools should start later in the morning.', 'Lập luận chính của cô ấy là các trường học nên bắt đầu muộn hơn vào buổi sáng.', 'ˈɑrɡjəmənt', 'noun'),
