  ('22222222-2222-4222-8222-000000000008', 'arrival', 'sự đến; người mới đến', 'Please inform the reception of your arrival time in advance.', 'Vui lòng báo trước cho lễ tân thời gian bạn đến.', 'əˈraɪvəl', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'aspect', 'khía cạnh; mặt', 'Money is an important aspect of choosing a university, but not the only one.', 'Tiền bạc là một khía cạnh quan trọng khi chọn trường đại học, nhưng không phải là duy nhất.', 'ˈæspɛkt', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'assessment', 'sự đánh giá', 'Teachers use regular assessment to check how well students are progressing.', 'Giáo viên sử dụng việc đánh giá thường xuyên để kiểm tra mức độ tiến bộ của học sinh.', 'əˈsɛsmənt', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'assignment', 'bài tập; nhiệm vụ được giao', 'I have to finish my history assignment before Monday morning.', 'Tôi phải hoàn thành bài tập lịch sử trước sáng thứ Hai.', 'əˈsaɪnmənt', 'noun'),
