  ('22222222-2222-4222-8222-000000000008', 'commitment', 'sự cam kết; sự tận tâm', 'The government has made a commitment to reduce carbon emissions by half.', 'Chính phủ đã cam kết giảm một nửa lượng khí thải carbon.', 'kəˈmɪtmənt', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'committee', 'ủy ban', 'The committee will meet next week to discuss the new budget.', 'Ủy ban sẽ họp vào tuần tới để thảo luận về ngân sách mới.', 'kəˈmɪti', 'noun'),
