  ('22222222-2222-4222-8222-000000000008', 'procedure', 'quy trình; thủ tục', 'All staff must follow the safety procedure if the fire alarm goes off.', 'Tất cả nhân viên phải tuân theo quy trình an toàn nếu chuông báo cháy reo.', 'prəˈsidʒɚ', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'process', 'quy trình; xử lý', 'Applying for a visa can be a long and complicated process.', 'Xin thị thực có thể là một quy trình dài và phức tạp.', 'ˈprɑsɛs', 'noun'),
  ('22222222-2222-4222-8222-000000000008', 'profile', 'hồ sơ; tiểu sử; mặt nghiêng', 'Remember to update your online profile before applying for jobs.', 'Hãy nhớ cập nhật hồ sơ trực tuyến của bạn trước khi nộp đơn xin việc.', 'ˈproʊfaɪl', 'noun'),
